const firstNames = [
  "Ada",
  "Maya",
  "Luna",
  "Kai",
  "Zara",
  "Noah",
  "Ivy",
  "Leo",
  "Nia",
  "Theo"
];

const lastNames = [
  "Stone",
  "River",
  "Knight",
  "Brooks",
  "Vale",
  "Wells",
  "Reed",
  "Storm",
  "Cole",
  "West"
];

function pickRandom(items, random) {
  return items[Math.floor(random() * items.length)];
}

export function generateName(options = {}) {
  const { includeMiddleInitial = false, random = Math.random } = options;
  const first = pickRandom(firstNames, random);
  const last = pickRandom(lastNames, random);

  if (!includeMiddleInitial) {
    return `${first} ${last}`;
  }

  const initial = String.fromCharCode(65 + Math.floor(random() * 26));
  return `${first} ${initial}. ${last}`;
}

export function generateNames(count = 1, options = {}) {
  if (!Number.isInteger(count) || count < 1) {
    throw new TypeError("count must be a positive integer");
  }

  return Array.from({ length: count }, () => generateName(options));
}

export const nameParts = {
  firstNames: [...firstNames],
  lastNames: [...lastNames]
};
